USE ecom;
ALTER TABLE products ADD COLUMN IF NOT EXISTS length_cm DECIMAL(8,2) NULL, ADD COLUMN IF NOT EXISTS width_cm DECIMAL(8,2) NULL, ADD COLUMN IF NOT EXISTS height_cm DECIMAL(8,2) NULL, ADD COLUMN IF NOT EXISTS dimension_unit ENUM('cm','in') NOT NULL DEFAULT 'cm';
ALTER TABLE shipping_info ADD COLUMN IF NOT EXISTS total_product_weight_grams INT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS packaging_weight_grams INT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS parcel_weight_grams INT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS parcel_length_cm DECIMAL(8,2) NULL, ADD COLUMN IF NOT EXISTS parcel_width_cm DECIMAL(8,2) NULL, ADD COLUMN IF NOT EXISTS parcel_height_cm DECIMAL(8,2) NULL, ADD COLUMN IF NOT EXISTS box_name VARCHAR(50) NULL, ADD COLUMN IF NOT EXISTS shippo_rate_id VARCHAR(100) NULL, ADD COLUMN IF NOT EXISTS shippo_transaction_id VARCHAR(100) NULL, ADD COLUMN IF NOT EXISTS label_url VARCHAR(600) NULL, ADD COLUMN IF NOT EXISTS shipping_status VARCHAR(50) NULL, ADD COLUMN IF NOT EXISTS parcel_override JSON NULL;
INSERT INTO settings (name,value) VALUES ('shipping_boxes','[{"name":"S","length":30,"width":20,"height":10,"weight_grams":120},{"name":"M","length":40,"width":30,"height":15,"weight_grams":180},{"name":"L","length":50,"width":35,"height":25,"weight_grams":260},{"name":"XL","length":60,"width":45,"height":35,"weight_grams":380}]') ON DUPLICATE KEY UPDATE name=name;
INSERT INTO settings (name,value) VALUES ('shipping_clearance_factor','1.15') ON DUPLICATE KEY UPDATE name=name;
INSERT INTO settings (name,value) VALUES ('shippo_label_file_type','PDF') ON DUPLICATE KEY UPDATE name=name;